mapper.select:
select  

    o.del_flag = '0'
    and o.id = #{id}
    and o.applicant_id = #{applicantId}
    and o.current_assignee_id = #{currentAssigneeId}
    and o.status = #{status}
    and o.category_id = #{categoryId}
    and o.urgency_level = #{urgencyLevel}
    and (o.warning_flag = '1' or o.overdue_flag = '1')

        and (o.order_no like concat('%', #{keyword}, '%')
          or o.title like concat('%', #{keyword}, '%')
          or o.description like concat('%', #{keyword}, '%'))


        and o.create_time >= #{params.beginTime}


        and o.create_time <= #{params.endTime}


        and o.create_time >= concat(#{beginTime}, ' 00:00:00')


        and o.create_time < date_add(#{endTime}, interval 1 day)

    ${params.dataScope}

order by o.create_time desc, o.id desc

mapper.update:
update wo_order
set warning_flag = #{warningFlag}, overdue_flag = #{overdueFlag},
    response_overdue = #{responseOverdue}, arrival_overdue = #{arrivalOverdue},
    finish_overdue = #{finishOverdue}, update_by = 'sla-scanner', update_time = #{updateTime}
where id = #{id} and status = #{status} and del_flag = '0'
  and (warning_flag != #{warningFlag} or overdue_flag != #{overdueFlag}
    or response_overdue != #{responseOverdue} or arrival_overdue != #{arrivalOverdue}
    or finish_overdue != #{finishOverdue})
